// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address currentOwner, address proposedNewOwner) public {
        vm.assume(currentOwner != address(0));
        vm.assume(proposedNewOwner != address(0));

        vm.prank(address(0));
        c.transferOwnership(currentOwner);

        vm.prank(currentOwner);
        c.transferOwnership(proposedNewOwner);

        assertTrue(c.owner() == proposedNewOwner);
    }
}
